import numpy as np

def make(agent=None, rewards=(), moving=(), prev_cells=None, walls=True):
    X = np.zeros((1, 500))
    if walls:
        for r in range(10):
            for c in range(10):
                if r in (0, 9) or c in (0, 9):
                    X[0, (r * 10 + c) * 5 + 3] = 1
    if agent is not None:
        r, c = agent
        X[0, (r * 10 + c) * 5 + 0] = 1
    for r, c in rewards:
        X[0, (r * 10 + c) * 5 + 2] = 1
    for r, c in moving:
        X[0, (r * 10 + c) * 5 + 1] = 1
    if prev_cells is None:
        prev_cells = [] if agent is None else [agent]
    for r, c in prev_cells:
        X[0, (r * 10 + c) * 5 + 4] = 1
    return X

