import numpy as np

def make_input(agent=None, reward=None, walls=False, prev=None, moving=None, obstacles=None):
    x = np.zeros(500)
    def setcell(r, c, ch, val=1):
        x[(r * 10 + c) * 5 + ch] = val
    if walls:
        for r in range(10):
            for c in range(10):
                if r == 0 or r == 9 or c == 0 or c == 9:
                    setcell(r, c, 3, 1)
    if agent:
        setcell(agent[0], agent[1], 0, 1)
    if reward:
        setcell(reward[0], reward[1], 2, 1)
    if prev:
        setcell(prev[0], prev[1], 4, 1)
    if moving:
        for (r, c) in moving:
            setcell(r, c, 1, 1)
    if obstacles:
        for (r, c) in obstacles:
            setcell(r, c, 3, 1)
    return x

# Sweep all inner agent positions with no walls, reward at top (1,4), prev=agent
inputs = []
positions = []
for r in range(1, 9):
    for c in range(1, 9):
        inputs.append(make_input(agent=(r, c), reward=(1, 4), walls=False, prev=(r, c)))
        positions.append((r, c))

X = np.array(inputs)
logits = forward(X)
argmax = np.argmax(logits, axis=1)

print("No-wall argmax grid (rows 1-8, cols 1-8):")
for r in range(1, 9):
    row = []
    for c in range(1, 9):
        idx = (r - 1) * 8 + (c - 1)
        row.append(str(argmax[idx]))
    print(r, " ".join(row))

for idx, (r, c) in enumerate(positions):
    if (r, c) == (5, 4):
        print(f"agent({r},{c}) logits:", np.round(logits[idx], 2), "argmax", argmax[idx])
    if argmax[idx] == 4:
        print(f"FOUND argmax 4 at agent({r},{c}) logits:", np.round(logits[idx], 2))

